using System;
using Ashfall.Core;
using Ashfall.Integration.Playable.HandsWeapons;
using Ashfall.Modules.WeaponHandling;
class HeadsetRecoilCases:IInteractionQuery {
 static int count;bool clear=true;
 public bool HasLineOfSight(string a,string b,Float3 o,Float3 p,float r){return clear;}
 static void Check(bool value,string why){count++;if(!value)throw new Exception(why);}
 static bool Near(float a,float b){return Math.Abs(a-b)<.00003f;}
 static bool Near(Float3 a,Float3 b){return Near(a.X,b.X)&&Near(a.Y,b.Y)&&Near(a.Z,b.Z);}
 static Float3 V(float x,float y,float z){return new Float3(x,y,z);}
 static readonly R23ShotPose Neutral=new R23ShotPose(V(2,1,-3),V(1,0,0),V(0,1,0),V(0,0,1));
 static HandlingInput Input(bool trigger=false){return new HandlingInput{Enabled=true,PrimaryTracked=true,SupportTracked=true,Desktop=true,Trigger=trigger,ForegripDistance=1};}
 void Run(){
  R23ShotPose model,shot;var muzzle=V(0,.045f,.69f);
  R23WeaponPoseMath.Resolve(Neutral,muzzle,.92f,0,0,0,false,out model,out shot);Check(Near(model.Origin,Neutral.Origin)&&Near(shot.Origin,Neutral.Point(muzzle,.92f))&&Near(shot.Forward,Neutral.Forward),"neutral exact source model.to_global muzzle without gun root recenter");
  R23WeaponPoseMath.Resolve(Neutral,muzzle,.92f,.06f,.12f,-.03f,false,out model,out shot);Check(model.Valid&&shot.Valid&&shot.Forward.Y>.11f&&shot.Forward.X>0,"source angular recoil moves next ballistic direction");Check(Near(shot.Origin,model.Point(muzzle,.92f)),"bullet starts on actual recoiled source muzzle");
  float[] rolls={0,.7f,1.57f,2.6f};float[] pitches={-.4f,0,.3f};
  foreach(float roll in rolls)foreach(float pitch in pitches){float c=(float)Math.Cos(roll),s=(float)Math.Sin(roll);var frame=new R23ShotPose(V(-4,1,7),V(c,s,0),V(-s,c,0),V(0,0,1));R23WeaponPoseMath.Resolve(frame,muzzle,1.32f,.04f,pitch,0,true,out model,out shot);Check(Near(shot.Forward.X,0)&&Near(shot.Forward.Y,(float)Math.Sin(pitch)),"upright signed pulse never turns sideways under wrist roll");Check(shot.Valid&&Near(shot.Origin,model.Point(muzzle,1.32f)),"rolled pulse publishes visible barrel frame");
   foreach(float distance in new[]{2f,5f,30f,180f})foreach(float eyeX in new[]{-.032f,.032f}){
    var lens=model.Point(V(0,.103f,-.0185f),1.32f);var eye=R23WeaponPoseMath.Add(lens,R23WeaponPoseMath.Add(R23WeaponPoseMath.Scale(shot.Forward,-.2f),V(eyeX,.006f,0)));var target=R23WeaponPoseMath.Add(shot.Origin,R23WeaponPoseMath.Scale(shot.Forward,distance));var center=R23SprScopeMath.ReticleCenter(shot,lens);var targetAngle=R23SprScopeMath.TargetTangent(shot,eye,target);var dotAngle=R23SprScopeMath.TargetTangent(shot,eye,center);
    Check(Near(R23SprScopeMath.SampleAngle(dotAngle.X,dotAngle.X,targetAngle.X),targetAngle.X)&&Near(R23SprScopeMath.SampleAngle(dotAngle.Y,dotAngle.Y,targetAngle.Y),targetAngle.Y),"both eye SPR red mark samples actual bullet target without vertical bias");
   }
  }
  foreach(float pole in new[]{-1f,1f}){var vertical=new R23ShotPose(V(0,0,0),V(1,0,0),V(0,0,-pole),V(0,pole,0));R23WeaponPoseMath.Resolve(vertical,muzzle,1,.04f,.3f,0,true,out model,out shot);Check(shot.Valid&&shot.Forward.Y<=1&&shot.Forward.Y>=-1,"world-up pulse remains finite at exact aim pole");}
  bool refused=false;try{R23WeaponPoseMath.Resolve(new R23ShotPose(),muzzle,1,0,0,0,false,out model,out shot);}catch(ArgumentException){refused=true;}Check(refused,"invalid non-unit pose refused");refused=false;try{R23WeaponPoseMath.Resolve(Neutral,muzzle,float.NaN,0,0,0,false,out model,out shot);}catch(ArgumentException){refused=true;}Check(refused,"nonfinite scale cannot publish ballistic pose");
  foreach(var row in ExpectedGripRows.Rows){var fit=R23WeaponGripFit.ForProfile(row.Id);Check(Near(fit.PrimaryModelPoint,row.Primary)&&Near(fit.PhysicalOffset,row.Offset)&&Near(fit.PitchRadians,row.Pitch),row.Id+" exact preserved source primary glove contact and physical fit");foreach(float scale in new[]{.55f,.92f,1.32f}){var actual=model.Point(fit.ModelContact(scale),scale);var primary=model.Point(fit.PrimaryModelPoint,scale);Check(Near(R23WeaponPoseMath.Add(actual,R23WeaponPoseMath.Scale(primary,-1)),model.Direction(row.Offset)),row.Id+" physical glove correction is not scaled twice");}}
  var round=new R23RoundState(new[]{"target"},this,true);round.SelectWeapon("akm");round.Step(0,Input(),false,false);var feedback=new R23WeaponFeedbackState("akm");
  R23WeaponPoseMath.Resolve(Neutral,muzzle,.945f,feedback.Distance,feedback.PitchRadians,feedback.YawRadians,false,out model,out shot);var acceptedFirst=shot;Check(round.Step(0,Input(true),false,false),"real AKM owner accepts initial shot");feedback.AcceptedShot(round.ActiveSnapshot.Shots,false);R23WeaponPoseMath.Resolve(Neutral,muzzle,.945f,feedback.Distance,feedback.PitchRadians,feedback.YawRadians,false,out model,out shot);Check(acceptedFirst.Forward.Y==0&&shot.Forward.Y>0,"accepted first shot captured before next recoil kick");
  feedback.Advance(1f/11);R23WeaponPoseMath.Resolve(Neutral,muzzle,.945f,feedback.Distance,feedback.PitchRadians,feedback.YawRadians,false,out model,out shot);var acceptedSecond=shot;Check(round.Step(1f/11,Input(true),false,false)&&acceptedSecond.Forward.Y>.01f&&round.ActiveLoaded==18,"next actual automatic bullet follows displayed recovery and debits once");
  clear=false;Check(!round.Hit("target",acceptedSecond.Origin,R23WeaponPoseMath.Add(acceptedSecond.Origin,R23WeaponPoseMath.Scale(acceptedSecond.Forward,5)),false,"akm")&&round.Hits==0&&round.ActiveLoaded==18,"existing world LOS denies wall target without inventing ammo refund");clear=true;
  long shots=round.ActiveSnapshot.Shots;Check(!round.Step(.2f,Input(true),false,true)&&round.ActiveSnapshot.Shots==shots,"pause still rejects real native firing");var missing=Input(true);missing.PrimaryTracked=false;Check(!round.Step(.2f,missing,false,false)&&round.ActiveSnapshot.Shots==shots,"tracking loss still rejects native firing");
  Check(round.ReadAmmoReserveFamily("rifle")==2400&&round.ReadAmmoReserveFamily("pistol")==1200&&round.ReadAmmoReserveFamily("smg")==1200&&round.ReadAmmoReserveFamily("sniper")==2400&&round.ReadAmmoReserveFamily("shells")==480,"resource tiles read real finite family pools independent of owned selection");int available;Check(!round.TryReadAmmoReserveFamily("unknown",out available)&&available==0,"unknown reserve family explicitly rejected");
  round.SetGripToggle(true);string copy;Check(round.CreateWeaponInstance("cx4",1,out copy)&&round.SelectWeapon(copy)&&round.Rifle.GripToggle,"new retained copy inherits actual native grip-toggle setting");round.SelectWeapon("m1014");Check(round.M1014.GripToggle,"shotgun receives actual native toggle setting");round.EnsureMagnumState("magnum/test");round.SelectWeapon("magnum");Check(round.Magnum.GripToggle,"Magnum receives actual native toggle setting");round.SetGripToggle(false);Check(!round.Magnum.GripToggle,"toggle false updates existing native owner");
  round.Step(0,Input(),false,false);var obstructed=Input(true);obstructed.HeadObstructed=true;Check(!round.Step(.2f,obstructed,false,false),"head obstruction still refuses accepted native shot");
  var hp=round.ReadTarget("target");float total=hp.Health+hp.Shield;int loaded=round.ActiveLoaded;Check(round.ApplyTargetDamage("target",25)&&Near(round.LastTargetDamage("target"),Math.Min(25,total))&&round.ActiveLoaded==loaded,"accepted explosive target bridge uses actual shared Health without gun ammo debit");Check(!round.ApplyTargetDamage("unknown",25)&&!round.ApplyTargetDamage("target",float.NaN)&&!round.ApplyTargetDamage("target",-1),"explosive bridge rejects unknown/nonfinite/negative target damage");Check(round.ApplyTargetDamage("target",1000)&&!round.ApplyTargetDamage("target",5),"dead actual target cannot accept phantom explosion damage");
  round.SetGripToggle(true);round.Reset();round.SelectWeapon("cx4");Check(round.Rifle.GripToggle&&round.ReadAmmoReserveFamily("rifle")==2400,"round reset retains actual support setting while explicit source round regrants reserves");
  round.SelectWeapon("spr");round.Step(0,Input(),false,false);Check(round.Step(.2f,Input(true),false,false)&&round.Hit("target",V(0,0,0),V(0,0,150),false,"spr"),"SPR source180m shot can create an actual far target hit");round.Step(.2f,Input(),false,false);round.Step(.2f,Input(true),false,false);Check(!round.Hit("target",V(0,0,0),V(0,0,181),false,"spr"),"source180m ballistic boundary rejects farther target");
  Console.WriteLine("PASS "+count+" source displayed-pose/SPR/grip/native-owner cases");
 }
 static void Main(){new HeadsetRecoilCases().Run();}
}
